from collections import defaultdict
def solve3(inp):
    g=[row[:] for row in inp]; h=len(g); w=len(g[0])
    pts=[(r,c) for r in range(h) for c in range(w) if g[r][c]!=0]
    dl=defaultdict(list); sl=defaultdict(list)
    for r,c in pts: dl[r-c].append((r,c)); sl[r+c].append((r,c))
    S=set(pts); out=[row[:] for row in g]
    def unit(a,b):  # returns (dr,dc) stepping from a toward b
        dr=b[0]-a[0]; dc=b[1]-a[1]
        return (dr//abs(dr) if dr else 0, dc//abs(dc) if dc else 0)
    for dv in list(dl):
        if len(dl[dv])<2: continue
        for sv in list(sl):
            if len(sl[sv])<2: continue
            rr,cc=(dv+sv)//2,(sv-dv)//2
            if (rr,cc) not in S: continue
            da=sorted(dl[dv], key=lambda p:abs(p[0]-rr)+abs(p[1]-cc))
            sa=sorted(sl[sv], key=lambda p:abs(p[0]-rr)+abs(p[1]-cc))
            dd=unit(da[0],da[1]); su=unit(sa[0],sa[1])
            tried=[]
            for dirc in [(dd[0],dd[1]),(-dd[0],-dd[1])]:
                for sir_ in [(su[0],su[1]),(-su[0],-su[1])]:
                    filled=False
                    for k in range(1,600):
                        r1=rr+dirc[0]*k; c1=cc+dirc[1]*k
                        r2=rr+sir_[0]*k; c2=cc+sir_[1]*k
                        if not(0<=r1<h and 0<=c1<w and 0<=r2<h and 0<=c2<w): break
                        lo,hi=min(c1,c2),max(c1,c2)
                        for c_ in range(lo+1,hi):
                            if g[r1][c_]==0: out[r1][c_]=2; filled=True
                    if filled: tried.append(((dirc,sir_)))
            if not tried: print('no wedge',dv,sv,'apex',(rr,cc),'dims',(len(da),len(sa)))
    return out

